731	// ---------------------------------------------------------------------------
732	// 离线兼容报告（compare 子命令）
733	// ---------------------------------------------------------------------------
734	//
735	// 兼容方向固定为 旧 -> 新：旧配置能按“方法 + 字面路径”匹配且通过正文检查的
736	// 每一种请求，在新配置中仍须匹配并通过。只比较接口存在性与请求接受条件；
737	// 响应状态/头/正文/延迟与序列差异不影响结论。
738	//
739	// 双方都配置 requestBody 时，比较的是“规则所接受 JSON 值的集合包含关系”
740	// L(旧规则) ⊆ L(新规则)，而不是文本比较或抽样请求；每个不兼容点都附一份
741	// 具体反例（旧规则接受、新规则拒绝的完整 JSON 值）。
742	
743	interface ReportReason {
744	  // 正文差异：RFC 6901 指针（根为 ""）；接口级原因（如接口删除）无此字段
745	  readonly pointer?: string;
746	  readonly message: string;
747	}
748	
749	interface ReportExample {
750	  readonly method: HttpMethod;
751	  readonly path: string;
752	  readonly headers: { readonly [name: string]: string };
753	  readonly body: string;
754	}
755	
756	interface EndpointReport {
757	  readonly method: HttpMethod;
758	  readonly path: string;
759	  readonly compatible: boolean;
760	  readonly reasons: readonly ReportReason[];
761	  readonly example?: ReportExample;
762	}
763	
764	interface CompareReport {
765	  readonly compatible: boolean;
766	  readonly oldFile: string;
767	  readonly newFile: string;
768	  readonly endpoints: readonly EndpointReport[];
769	}
770	
771	interface BodyViolation {
772	  readonly pointer: string;
773	  readonly message: string;
774	  // 完整请求正文反例：被旧规则接受、被新规则拒绝
775	  readonly value: unknown;
776	}
777	
778	// 生成被规则接受的最小 JSON 值：object 只含必填字段，array 取空数组。
779	// 字段名可能是 "" 或 "__proto__"，一律用无原型对象按自有字段构造。
780	function sampleValue(rule: BodyRule): unknown {
781	  switch (rule.kind) {
782	    case 'string':
783	      return 'contractlab';
784	    case 'number':
785	    case 'integer':
786	      return 0;
787	    case 'boolean':
788	      return false;
789	    case 'null':
790	      return null;
791	    case 'array':
792	      return [];
793	    case 'object': {
794	      const obj: Record<string, unknown> = Object.create(null);
795	      for (const [name, field] of rule.fields) {
796	        if (field.required) {
797	          obj[name] = sampleValue(field.rule);
798	        }
799	      }
800	      return obj;
801	    }
802	  }
803	}
804	
805	// 在 object 规则的最小样本上补一个字段（字段值本身须被该字段规则接受）
806	function sampleObjectWith(
807	  rule: Extract<BodyRule, { kind: 'object' }>,
808	  name: string,
809	  value: unknown,
810	): Record<string, unknown> {
811	  const obj = sampleValue(rule) as Record<string, unknown>;
812	  obj[name] = value;
813	  return obj;
814	}
815	
816	// 生成被规则拒绝的 JSON 值（顶层类型即不符；任何规则都存在这样的值）
817	function violateValue(rule: BodyRule): unknown {
818	  switch (rule.kind) {
819	    case 'number':
820	      return 'contractlab'; // 非数字
821	    case 'integer':
822	      return 0.5; // 非整数
823	    default:
824	      return 0; // 非 string / boolean / null / object / array
825	  }
826	}
827	
828	function kindLabel(rule: BodyRule): string {
829	  if (rule.kind === 'object') {
830	    return rule.additionalProperties ? 'object（允许未声明字段）' : 'object（拒绝未声明字段）';
831	  }
832	  return rule.kind;
833	}
834	
835	// 选一个两个规则都未声明的字段名，用于构造“额外字段”反例
836	function freshFieldName(
837	  oldFields: ReadonlyMap<string, FieldRule>,
838	  newFields: ReadonlyMap<string, FieldRule>,
839	): string {
840	  for (let i = 0; ; i += 1) {
841	    const name = i === 0 ? 'extra' : `extra_${i}`;
842	    if (!oldFields.has(name) && !newFields.has(name)) {
843	      return name;
844	    }
845	  }
846	}
847	
848	// 递归判定 L(oldRule) ⊆ L(newRule)；把发现的每个反例（连同完整正文样本）推入 out。
849	// 不变式：value 必被 oldRule 接受、被 newRule 拒绝；pointer 用 RFC 6901 定位差异。
850	function collectViolations(
851	  oldRule: BodyRule,
852	  newRule: BodyRule,
853	  pointer: string,
854	  out: BodyViolation[],
855	): void {
856	  if (newRule.kind !== 'object' && newRule.kind !== 'array') {
857	    // 标量：仅同名兼容，外加 integer 放宽为 number；其余组合两集合相交为空或有差异
858	    const compatible =
859	      oldRule.kind === newRule.kind || (oldRule.kind === 'integer' && newRule.kind === 'number');
860	    if (!compatible) {
861	      // number -> integer 时样本必须是非整数，否则 0 会被新规则接受
862	      const value =
863	        oldRule.kind === 'number' && newRule.kind === 'integer' ? 0.5 : sampleValue(oldRule);
864	      out.push({
865	        pointer,
866	        value,
867	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 ${newRule.kind}`,
868	      });
869	    }
870	    return;
871	  }
872	
873	  if (newRule.kind === 'array') {
874	    if (oldRule.kind !== 'array') {
875	      out.push({
876	        pointer,
877	        value: sampleValue(oldRule),
878	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 array`,
879	      });
880	      return;
881	    }
882	    // 元素规则收紧：用非空数组 [反例] 体现（空数组双方都会接受）
883	    const sub: BodyViolation[] = [];
884	    collectViolations(oldRule.items, newRule.items, `${pointer}/0`, sub);
885	    for (const s of sub) {
886	      out.push({ pointer: s.pointer, message: s.message, value: [s.value] });
887	    }
888	    return;
889	  }
890	
891	  // newRule.kind === 'object'
892	  if (oldRule.kind !== 'object') {
893	    out.push({
894	      pointer,
895	      value: sampleValue(oldRule),
896	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 object`,
897	    });
898	    return;
899	  }
900	
901	  // (a) 新规则的必填字段必须被旧规则保证存在（旧规则未声明或仅可选即存在反例）
902	  for (const [name, newField] of newRule.fields) {
903	    if (!newField.required) {
904	      continue;
905	    }
906	    const oldField = oldRule.fields.get(name);
907	    if (!oldField || !oldField.required) {
908	      out.push({
909	        pointer: `${pointer}/${escapePointerSegment(name)}`,
910	        // 旧规则的最小样本不含可缺省/未声明字段，恰为反例
911	        value: sampleValue(oldRule),
912	        message: `新规则要求必填字段 ${JSON.stringify(name)}，旧规则允许缺省该字段`,
913	      });
914	    }
915	  }
916	
917	  // (b) 旧规则声明的字段，在新规则下仍须被接受
918	  for (const [name, oldField] of oldRule.fields) {
919	    const childPointer = `${pointer}/${escapePointerSegment(name)}`;
920	    const newField = newRule.fields.get(name);
921	    if (!newField) {
922	      if (!newRule.additionalProperties) {
923	        out.push({
924	          pointer: childPointer,
925	          value: sampleObjectWith(oldRule, name, sampleValue(oldField.rule)),
926	          message: `新规则拒绝旧规则允许的字段 ${JSON.stringify(name)}（新规则未声明且 additionalProperties 为 false）`,
927	        });
928	      }
929	      continue;
930	    }
931	    const sub: BodyViolation[] = [];
932	    collectViolations(oldField.rule, newField.rule, childPointer, sub);
933	    for (const s of sub) {
934	      out.push({
935	        pointer: s.pointer,
936	        message: s.message,
937	        value: sampleObjectWith(oldRule, name, s.value),
938	      });
939	    }
940	  }
941	
942	  // (c) 旧规则允许未声明的额外字段时，新规则必须同样放行这些字段
943	  if (oldRule.additionalProperties) {
944	    if (!newRule.additionalProperties) {
945	      const name = freshFieldName(oldRule.fields, newRule.fields);
946	      out.push({
947	        pointer: `${pointer}/${escapePointerSegment(name)}`,
948	        value: sampleObjectWith(oldRule, name, 0),
949	        message: '旧规则允许未声明的额外字段，新规则拒绝（additionalProperties 为 false）',
950	      });
951	    } else {
952	      // 新规则虽放行额外字段，但其新声明的字段会约束旧版原本自由的取值
953	      for (const [name, newField] of newRule.fields) {
954	        if (oldRule.fields.has(name)) {
955	          continue;
956	        }
957	        out.push({
958	          pointer: `${pointer}/${escapePointerSegment(name)}`,
959	          value: sampleObjectWith(oldRule, name, violateValue(newField.rule)),
960	          message: `旧规则对额外字段 ${JSON.stringify(name)} 不限制取值，新规则要求其为 ${kindLabel(newField.rule)}`,
961	        });
962	      }
963	    }
964	  }
965	}
966	
967	// 旧接口被旧配置接受的一个请求样本（用于“接口已删除”反例）
968	function acceptedRequestExample(endpoint: EndpointSpec): ReportExample {
969	  if (endpoint.bodyRule) {
970	    return {
971	      method: endpoint.method,
972	      path: endpoint.path,
973	      headers: { 'Content-Type': 'application/json' },
974	      body: JSON.stringify(sampleValue(endpoint.bodyRule)),
975	    };
976	  }
977	  return { method: endpoint.method, path: endpoint.path, headers: {}, body: '' };
978	}
979	
980	function compareEndpoint(oldEp: EndpointSpec, newEp: EndpointSpec | undefined): EndpointReport {
981	  const base = { method: oldEp.method, path: oldEp.path };
982	
983	  if (!newEp) {
984	    return {
985	      ...base,
986	      compatible: false,
987	      reasons: [
988	        { message: '新配置中不存在该接口：按 方法 + 字面路径 匹配不到，旧客户端的调用将得到 404' },
989	      ],
990	      example: acceptedRequestExample(oldEp),
991	    };
992	  }
993	
994	  if (!oldEp.bodyRule && !newEp.bodyRule) {
995	    return { ...base, compatible: true, reasons: [] };
996	  }
997	
998	  if (!oldEp.bodyRule && newEp.bodyRule) {
999	    // 旧版允许任意媒体类型与正文；新版启用校验即存在被拒绝的旧请求
1000	    return {
1001	      ...base,
1002	      compatible: false,
1003	      reasons: [
1004	        {
1005	          pointer: '',
1006	          message: '旧接口不校验请求正文（任意媒体类型与正文均可），新接口启用了 requestBody 正文校验',
1007	        },
1008	      ],
1009	      example: {
1010	        ...base,
1011	        headers: { 'Content-Type': 'application/json' },
1012	        body: JSON.stringify(violateValue(newEp.bodyRule)),
1013	      },
1014	    };
1015	  }
1016	
1017	  if (oldEp.bodyRule && !newEp.bodyRule) {
1018	    return { ...base, compatible: true, reasons: [] }; // 移除规则更宽松
1019	  }
1020	
1021	  const violations: BodyViolation[] = [];
1022	  collectViolations(oldEp.bodyRule as BodyRule, newEp.bodyRule as BodyRule, '', violations);
1023	  if (violations.length === 0) {
1024	    return { ...base, compatible: true, reasons: [] };
1025	  }
1026	  return {
1027	    ...base,
1028	    compatible: false,
1029	    reasons: violations.map((v) => ({ pointer: v.pointer, message: v.message })),
1030	    example: {
1031	      ...base,
1032	      headers: { 'Content-Type': 'application/json' },
1033	      body: JSON.stringify(violations[0].value),
1034	    },
1035	  };
1036	}
1037	
1038	function compareConfigs(
1039	  oldSpecs: readonly EndpointSpec[],
1040	  newSpecs: readonly EndpointSpec[],
1041	  oldFile: string,
1042	  newFile: string,
1043	): CompareReport {
1044	  const newByKey = new Map<string, EndpointSpec>();
1045	  for (const spec of newSpecs) {
1046	    newByKey.set(`${spec.method} ${spec.path}`, spec);
1047	  }
1048	  const endpoints = oldSpecs.map((spec) =>
1049	    compareEndpoint(spec, newByKey.get(`${spec.method} ${spec.path}`)),
1050	  );
1051	  return {
1052	    compatible: endpoints.every((ep) => ep.compatible),
1053	    oldFile,
1054	    newFile,
1055	    endpoints,
1056	  };
1057	}
