1059	async function runCompare(oldArg: string, newArg: string): Promise<never> {
1060	  const oldFile = path.resolve(oldArg);
1061	  const newFile = path.resolve(newArg);
1062	
1063	  const attempt = async (
1064	    file: string,
1065	  ): Promise<{ specs?: EndpointSpec[]; error?: string }> => {
1066	    try {
1067	      return { specs: await loadSpecsFromFile(file) };
1068	    } catch (e) {
1069	      return { error: describeError(e) };
1070	    }
1071	  };
1072	
1073	  // 两份文件都完整经历 读取 -> 解析 -> 严格校验；任一失败则不输出任何报告
1074	  const [oldResult, newResult] = await Promise.all([attempt(oldFile), attempt(newFile)]);
1075	  let failed = false;
1076	  if (oldResult.error !== undefined) {
1077	    process.stderr.write(`${APP_NAME}: compare 旧文件：${oldResult.error}\n`);
1078	    failed = true;
1079	  }
1080	  if (newResult.error !== undefined) {
1081	    process.stderr.write(`${APP_NAME}: compare 新文件：${newResult.error}\n`);
1082	    failed = true;
1083	  }
1084	  if (failed) {
1085	    process.exit(2);
1086	  }
1087	
1088	  const report = compareConfigs(
1089	    oldResult.specs as EndpointSpec[],
1090	    newResult.specs as EndpointSpec[],
1091	    oldFile,
1092	    newFile,
1093	  );
1094	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
1095	  process.exit(report.compatible ? 0 : 1);
1096	}
