1109	// 进程内请求记录：与配置版本、序列相互独立，reload 与清空都不影响编号单调
1110	const requestLog = new RequestLog();
1111	
1112	// 尚未发出的延迟响应定时器，关闭时统一取消
1113	const pendingTimers = new Set<ReturnType<typeof setTimeout>>();
