1115	// 重载按“触发顺序”串行处理：后一个 reload 必定在前一个落定后才读文件
1116	let reloadChain: Promise<unknown> = Promise.resolve();
1117	
1118	function triggerReload(): Promise<ReloadResult> {
1119	  const job = reloadChain.then(async (): Promise<ReloadResult> => {
1120	    try {
1121	      // 校验通过前只构造局部变量，任何失败都不会触碰 activeState
1122	      const next = await loadStateFromFile(configFile, activeState.version + 1);
1123	      activeState = next; // 单次同步赋值：请求不可能看到混合配置
1124	      return { ok: true, version: activeState.version };
1125	    } catch (e) {
1126	      // 不修改配置/版本，不重置序列；旧场景的正常消费继续
1127	      return { ok: false, version: activeState.version, error: describeError(e) };
1128	    }
1129	  });
1130	  // 失败也不能打断后续 reload 的排队
1131	  reloadChain = job.then(
1132	    () => undefined,
1133	    () => undefined,
1134	  );
1135	  return job;
1136	}
