1187	// ---------------------------------------------------------------------------
1188	// 计划响应快照与写出跟踪
1189	// ---------------------------------------------------------------------------
1190	//
1191	// 业务/框架响应在“请求完整接收”那一刻就构造为一份计划快照：
1192	// 记录中保存的状态/应用层头/正文与随后真正写上线的字节共用同一份数据，
1193	// reload 不影响在途请求（它持有的是快照而非当前配置）。
1194	
1195	function freezeHeaders(headers: { [name: string]: string }): { readonly [name: string]: string } {
1196	  return Object.freeze(headers);
1197	}
1198	
1199	// 场景响应的应用层头：配置头 + 服务器填写的准确版本头（+ 必要时的默认 Content-Type）。
1200	// 不含 Content-Length/Connection/Date/Transfer-Encoding 等传输层自动头。
1201	function buildSceneHeaders(
1202	  item: ResponseSpec,
1203	  version: number,
1204	): { readonly [name: string]: string } {
1205	  const headers = versionHeaders(version);
1206	  let contentTypeSet = false;
1207	  for (const [name, value] of Object.entries(item.headers)) {
1208	    const lower = name.toLowerCase();
1209	    // 版本头由服务器填写且必须唯一准确：配置中的同名头（含大小写变体）可加载，发送时忽略其值
1210	    if (lower === VERSION_HEADER.toLowerCase()) {
1211	      continue;
1212	    }
1213	    if (lower === 'content-type') {
1214	      contentTypeSet = true;
1215	    }
1216	    headers[name] = value;
1217	  }
1218	  // 文本正文的默认内容类型；配置显式给出时不覆盖
1219	  if (!contentTypeSet && item.body !== '') {
1220	    headers['Content-Type'] = 'text/plain; charset=utf-8';
1221	  }
1222	  return freezeHeaders(headers);
1223	}
1224	
1225	function buildScenePlanned(item: ResponseSpec, version: number): PlannedResponseSnapshot {
1226	  return {
1227	    kind: 'scene',
1228	    status: item.status,
1229	    headers: buildSceneHeaders(item, version),
1230	    body: item.body,
1231	  };
1232	}
