1234	function buildFrameworkPlanned(
1235	  status: number,
1236	  version: number,
1237	  body: string,
1238	  contentType: string,
1239	): PlannedResponseSnapshot {
1240	  return {
1241	    kind: 'framework',
1242	    status,
1243	    headers: freezeHeaders(versionHeaders(version, { 'Content-Type': contentType })),
1244	    body,
1245	  };
1246	}
