1442	async function handleAdmin(method: string, pathname: string, res: http.ServerResponse): Promise<void> {
1443	  if (pathname === HEALTH_PATH) {
1444	    if (method === 'GET') {
1445	      sendJson(res, 200, { status: 'ok', version: activeState.version }, activeState.version);
1446	    } else {
1447	      sendNotFound(res);
1448	    }
1449	    return;
1450	  }
1451	
1452	  if (pathname === RELOAD_PATH) {
1453	    if (method === 'POST') {
1454	      const result = await triggerReload();
1455	      sendJson(res, 200, result, result.version);
1456	    } else {
1457	      sendNotFound(res);
1458	    }
1459	    return;
1460	  }
1461	
1462	  if (pathname === REQUESTS_PATH) {
1463	    if (method === 'GET') {
1464	      const records = requestLog.snapshot();
1465	      sendJson(
1466	        res,
1467	        200,
1468	        { note: requestsUsageNote(), count: records.length, records },
1469	        activeState.version,
1470	      );
1471	    } else {
1472	      sendNotFound(res);
1473	    }
1474	    return;
1475	  }
1476	
1477	  if (pathname === REQUESTS_CLEAR_PATH) {
1478	    if (method === 'POST') {
1479	      const removed = requestLog.clear();
1480	      sendJson(
1481	        res,
1482	        200,
1483	        { ok: true, removed, note: requestsUsageNote() },
1484	        activeState.version,
1485	      );
1486	    } else {
1487	      sendNotFound(res);
1488	    }
1489	    return;
1490	  }
1491	
1492	  // 管理范围内的未知路径：仍是管理请求，不记录、不消费
1493	  sendNotFound(res);
1494	}
