1520	async function startServer(configArg: string, port: number): Promise<void> {
1521	  configFile = path.resolve(configArg);
1522	
1523	  // 先读配置：配置无效时根本不会创建监听
1524	  activeState = await loadStateFromFile(configFile, 1);
1525	
1526	  server = http.createServer((req, res) => {
1527	    dispatch(req, res).catch(() => {
1528	      try {
1529	        req.socket.destroy();
1530	      } catch {
1531	        // 套接字可能已销毁
1532	      }
1533	    });
1534	  });
1535	
1536	  await new Promise<void>((resolve, reject) => {
1537	    server.once('error', reject);
1538	    // 仅监听本机回环地址
1539	    server.listen(port, '127.0.0.1', resolve);
1540	  });
1541	
1542	  const address = server.address();
1543	  const actualPort = typeof address === 'object' && address ? address.port : port;
1544	  process.stdout.write(
1545	    `${APP_NAME}: listening on http://127.0.0.1:${actualPort}\n` +
1546	      `${APP_NAME}: config ${configFile} (version 1, ${activeState.endpoints.size} endpoints)\n`,
1547	  );
1548	
1549	  const onSignal = (): void => shutdown();
1550	  process.on('SIGINT', onSignal);
1551	  process.on('SIGTERM', onSignal);
1552	}
