1580	    '                        不启动监听；报告以 JSON 写往 stdout：',
1581	    '                        兼容退出 0，不兼容退出 1，',
1582	    '                        参数/读取/解析/校验失败退出 2（错误写 stderr）',
1583	    '',
1584	    '管理入口（路径前缀 /__contractlab/ 为业务接口保留区之外的保留前缀）：',
1585	    '  GET  /__contractlab/health          健康查询，返回当前配置版本',
1586	    '  POST /__contractlab/reload          重新读取并热更新同一配置文件',
1587	    '  GET  /__contractlab/requests        查询本次进程内的请求记录（一致快照）',
1588	    '  POST /__contractlab/requests/clear  清空请求记录（不取消响应、不改配置）',
1589	    '',
1590	    '配置格式见 README.md。',
1591	  ].join('\n');
1592	}
1593	
1594	function cliFail(message: string): never {
1595	  process.stderr.write(`${APP_NAME}: ${message}\n`);
1596	  process.stderr.write(`运行 'node app.ts --help' 查看用法。\n`);
1597	  process.exit(2);
1598	}
1599	
1600	interface ServeOptions {
1601	  config: string;
1602	  port: number;
1603	}
1604	
1605	function parseServeArgv(argv: readonly string[]): ServeOptions {
1606	  let config: string | undefined;
1607	  let port: number | undefined;
1608	
1609	  const readValue = (flag: string, inline: string | undefined, index: number): [string, number] => {
1610	    if (inline !== undefined) {
1611	      return [inline, index];
1612	    }
1613	    const value = argv[index + 1];
1614	    if (value === undefined) {
1615	      cliFail(`serve: 参数 ${flag} 缺少取值`);
1616	    }
1617	    return [value as string, index + 1];
1618	  };
1619	
1620	  for (let i = 0; i < argv.length; i += 1) {
1621	    const token = argv[i];
1622	    if (token === '--help' || token === '-h') {
1623	      process.stdout.write(`${helpText()}\n`);
1624	      process.exit(0);
1625	    }
1626	
1627	    let flag = token;
1628	    let inline: string | undefined;
1629	    const eq = token.indexOf('=');
1630	    if (eq >= 0) {
1631	      flag = token.slice(0, eq);
1632	      inline = token.slice(eq + 1);
1633	    }
1634	
1635	    if (flag === '--config' || flag === '-c') {
1636	      [config, i] = readValue(flag, inline, i);
1637	    } else if (flag === '--port' || flag === '-p') {
1638	      let value: string;
1639	      [value, i] = readValue(flag, inline, i);
1640	      if (!/^\d+$/.test(value)) {
1641	        cliFail(`serve: 端口必须是整数，收到 "${value}"`);
1642	      }
1643	      port = Number(value);
1644	      if (port < 0 || port > 65535) {
1645	        cliFail(`serve: 端口必须在 0 至 65535 之间，收到 ${port}`);
1646	      }
1647	    } else {
1648	      cliFail(`serve: 不支持的命令行参数: ${token}`);
1649	    }
1650	  }
1651	
1652	  if (config === undefined) {
1653	    cliFail('serve: 缺少必填参数 --config <file>');
1654	  }
1655	  if (port === undefined) {
1656	    cliFail('serve: 缺少必填参数 --port <port>');
1657	  }
1658	  return { config, port };
1659	}
1660	
1661	interface CompareOptions {
1662	  oldFile: string;
1663	  newFile: string;
1664	}
1665	
1666	function parseCompareArgv(argv: readonly string[]): CompareOptions {
1667	  let oldFile: string | undefined;
1668	  let newFile: string | undefined;
1669	
1670	  const readValue = (flag: string, inline: string | undefined, index: number): [string, number] => {
1671	    if (inline !== undefined) {
1672	      return [inline, index];
1673	    }
1674	    const value = argv[index + 1];
1675	    if (value === undefined) {
1676	      cliFail(`compare: 参数 ${flag} 缺少取值`);
1677	    }
1678	    return [value as string, index + 1];
1679	  };
1680	
1681	  for (let i = 0; i < argv.length; i += 1) {
1682	    const token = argv[i];
1683	    if (token === '--help' || token === '-h') {
1684	      process.stdout.write(`${helpText()}\n`);
1685	      process.exit(0);
1686	    }
1687	
1688	    let flag = token;
1689	    let inline: string | undefined;
1690	    const eq = token.indexOf('=');
1691	    if (eq >= 0) {
1692	      flag = token.slice(0, eq);
1693	      inline = token.slice(eq + 1);
1694	    }
1695	
1696	    if (flag === '--old' || flag === '-o') {
1697	      [oldFile, i] = readValue(flag, inline, i);
1698	    } else if (flag === '--new' || flag === '-n') {
1699	      [newFile, i] = readValue(flag, inline, i);
1700	    } else {
1701	      cliFail(`compare: 不支持的命令行参数: ${token}`);
1702	    }
1703	  }
1704	
1705	  if (oldFile === undefined) {
1706	    cliFail('compare: 缺少必填参数 --old <file>');
1707	  }
1708	  if (newFile === undefined) {
1709	    cliFail('compare: 缺少必填参数 --new <file>');
1710	  }
1711	  return { oldFile, newFile };
1712	}
1713	
1714	function main(): void {
1715	  const argv = process.argv.slice(2);
1716	
1717	  // 保留行为：无参数、--help、-h 显示应用名与帮助
1718	  if (
1719	    argv.length === 0 ||
1720	    (argv.length === 1 && (argv[0] === '--help' || argv[0] === '-h'))
1721	  ) {
1722	    process.stdout.write(`${helpText()}\n`);
1723	    return;
1724	  }
1725	
1726	  if (argv[0] === 'serve') {
1727	    const options = parseServeArgv(argv.slice(1));
1728	    startServer(options.config, options.port).catch((e: unknown) => {
1729	      process.stderr.write(`${APP_NAME}: 启动失败：${describeError(e)}\n`);
1730	      process.exit(1);
1731	    });
1732	    return;
1733	  }
1734	
1735	  if (argv[0] === 'compare') {
1736	    const options = parseCompareArgv(argv.slice(1));
1737	    runCompare(options.oldFile, options.newFile).catch((e: unknown) => {
1738	      process.stderr.write(`${APP_NAME}: compare 失败：${describeError(e)}\n`);
1739	      process.exit(2);
1740	    });
1741	    return;
1742	  }
1743	
1744	  // 不支持的命令行参数：报错并以状态码 2 退出
1745	  process.stderr.write(`${APP_NAME}: 不支持的命令行参数: ${argv.join(' ')}\n`);
1746	  process.stderr.write(`运行 'node app.ts --help' 查看用法。\n`);
