200	// ---------------------------------------------------------------------------
201	
202	export interface RuleJson {
203	  readonly type: string;
204	  readonly fields?: { readonly [name: string]: RuleJson & { readonly required?: boolean } };
205	  readonly additionalProperties?: boolean;
206	  readonly items?: RuleJson;
207	  readonly required?: boolean;
208	}
209	
210	function isPlainJsonObject(value: unknown): value is Record<string, unknown> {
211	  return typeof value === 'object' && value !== null && !Array.isArray(value);
212	}
213	
214	export function accepts(rule: RuleJson, value: unknown): boolean {
215	  switch (rule.type) {
216	    case 'string':
217	      return typeof value === 'string';
218	    case 'boolean':
219	      return typeof value === 'boolean';
220	    case 'null':
221	      return value === null;
222	    case 'number':
223	      return typeof value === 'number' && Number.isFinite(value);
224	    case 'integer':
225	      return typeof value === 'number' && Number.isInteger(value);
226	    case 'array':
227	      return Array.isArray(value) && value.every((item) => accepts(rule.items as RuleJson, item));
228	    case 'object': {
229	      if (!isPlainJsonObject(value)) {
230	        return false;
231	      }
232	      const fields = rule.fields ?? {};
233	      for (const [name, fieldRule] of Object.entries(fields)) {
234	        const has = Object.prototype.hasOwnProperty.call(value, name);
235	        if (!has) {
236	          if (fieldRule.required === true) {
237	            return false;
238	          }
239	        } else if (!accepts(fieldRule, value[name])) {
240	          return false;
241	        }
242	      }
243	      if (rule.additionalProperties !== true) {
244	        for (const key of Object.keys(value)) {
245	          if (!Object.prototype.hasOwnProperty.call(fields, key)) {
246	            return false;
247	          }
248	        }
249	      }
250	      return true;
251	    }
252	    default:
253	      throw new Error(`参考实现遇到未知规则类型: ${JSON.stringify(rule.type)}`);
254	  }
255	}
256	
257	// ---------------------------------------------------------------------------
258	// 有限代表值域
259	// ---------------------------------------------------------------------------
260	//
261	// 设计目标：对本测试矩阵中的每一对（旧规则, 新规则），只要二者接受的 JSON
262	// 值集合不同，域中就存在一个见证值。为此域必须区分：
263	// - 整数与非整数（0/1 与 0.5）：区分 integer 与 number 的双向变化；
264	// - 字段缺失与 null（删除变体 与 显式 null）：区分“必填缺失”与“类型为 null”；
265	// - 空数组与非空数组（[] 与 [v]）：元素规则收紧在空数组上不可见；
266	// - 已声明字段与未声明额外字段（zz_extra）：区分 additionalProperties 两种策略；
267	// - 对象与数组的嵌套（递归到 MAX_DEPTH 层）。
268	//
269	// 构造方式（对每层对象规则）：
270	// - 标量代表值全集；
271	// - 空数组，以及元素代表值构成的单元素数组（若任一规则声明了数组元素规则，
272	//   元素域递归生成，否则用标量）；
273	// - 空对象、仅含额外字段的对象；
274	// - “基对象”：两规则声明字段的并集各取一个双方（退化为旧方）都接受的值，
275	//   再叠加额外字段；随后对每个字段做“删除”与“逐代表值替换”变体。
276	// 这样，新增必填字段由删除变体见证、字段类型收紧由替换变体见证、
277	// additionalProperties 收紧由叠加额外字段的对象见证、嵌套收紧由递归域见证。
278	//
279	// 注意：这只是针对本矩阵所测规则对的充分见证域，不构成对任意递归规则
280	// 包含关系的证明；矩阵中每条用例的期望都来自该域的穷举结果。
281	
282	const MAX_DEPTH = 2;
283	
284	// 标量代表值：覆盖 string（含空串）、整数、非整数、boolean、null
285	const SCALAR_REPS: readonly unknown[] = ['txt', '', 0, 1, 0.5, true, false, null];
286	
287	type FieldMap = { readonly [name: string]: RuleJson & { readonly required?: boolean } };
288	
289	function objectFields(rule: RuleJson | undefined): FieldMap {
290	  return rule !== undefined && rule.type === 'object' ? (rule.fields ?? {}) : {};
291	}
292	
293	function pickBase(
294	  subDomain: readonly unknown[],
295	  oldField: RuleJson | undefined,
296	  newField: RuleJson | undefined,
297	): unknown {
298	  const ok = (rule: RuleJson | undefined, v: unknown): boolean =>
299	    rule === undefined || accepts(rule, v);
300	  // 优先选双方规则都接受的值（基对象尽量是“好公民”），退化为旧规则接受，再退化为首元素
301	  return (
302	    subDomain.find((v) => ok(oldField, v) && ok(newField, v)) ??
303	    subDomain.find((v) => ok(oldField, v)) ??
304	    subDomain[0]
305	  );
306	}
307	
308	export function domainFor(
309	  oldRule: RuleJson | undefined,
310	  newRule: RuleJson | undefined,
311	  depth = 0,
312	): unknown[] {
313	  const values: unknown[] = [...SCALAR_REPS];
314	  if (depth >= MAX_DEPTH) {
315	    values.push([], {});
316	    return values;
317	  }
318	
319	  // 数组：空数组 + 元素代表值的单元素数组
320	  values.push([]);
321	  const itemOld = oldRule !== undefined && oldRule.type === 'array' ? oldRule.items : undefined;
322	  const itemNew = newRule !== undefined && newRule.type === 'array' ? newRule.items : undefined;
323	  const itemDomain =
324	    itemOld !== undefined || itemNew !== undefined
325	      ? domainFor(itemOld, itemNew, depth + 1)
326	      : SCALAR_REPS;
327	  for (const v of itemDomain) {
328	    values.push([v]);
329	  }
330	
331	  // 对象：空对象、额外字段对象、基对象及其删除/替换变体
332	  const fieldsOld = objectFields(oldRule);
333	  const fieldsNew = objectFields(newRule);
334	  const names = [...new Set([...Object.keys(fieldsOld), ...Object.keys(fieldsNew)])];
335	  let extra = 'zz_extra';
336	  while (names.includes(extra)) {
337	    extra = `${extra}_x`;
338	  }
339	  values.push({}, { [extra]: 0 }, { [extra]: 'txt' });
340	
341	  if (names.length > 0) {
342	    const subDomains = new Map<string, unknown[]>();
343	    const base: Record<string, unknown> = {};
344	    for (const name of names) {
345	      const sd = domainFor(fieldsOld[name], fieldsNew[name], depth + 1);
346	      subDomains.set(name, sd);
347	      base[name] = pickBase(sd, fieldsOld[name], fieldsNew[name]);
348	    }
349	    values.push(base, { ...base, [extra]: 0 }, { ...base, [extra]: 'txt' });
350	    for (const name of names) {
351	      const deleted = { ...base };
352	      delete deleted[name];
353	      values.push(deleted);
354	      for (const v of subDomains.get(name) as unknown[]) {
355	        if (!Object.is(v, base[name])) {
356	          values.push({ ...base, [name]: v });
357	        }
358	      }
359	    }
360	  }
361	
362	  return values;
363	}
