    },
    {
      name: '必填字段被另一分支禁止出现',
      schema: {
        allOf: [
          { type: 'object', properties: { a: { type: 'string' } }, required: ['a'], additionalProperties: false },
          { type: 'object', properties: {}, additionalProperties: false },
        ],
      },
      expect: /交集为空/,
    },
    {
      name: '同名字段类型相交为空（必填）',
